import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import axios from "axios";
import "./Emergency.css";

const Emergency = () => {
  const navigate = useNavigate();
  const [contacts, setContacts] = useState([]);

  // Fetch contacts from backend
  useEffect(() => {
    axios
      .get("http://localhost:5001/api/contacts")
      .then((res) => setContacts(res.data))
      .catch((err) => console.error("Error fetching contacts:", err));
  }, []);

  const handleCall = async (contact) => {
    try {
      // Optional: get user location
      let latitude = null;
      let longitude = null;
      if (navigator.geolocation) {
        navigator.geolocation.getCurrentPosition((position) => {
          latitude = position.coords.latitude;
          longitude = position.coords.longitude;

          // Log emergency call to backend
          axios
            .post("http://localhost:5001/api/calls", {
              contactName: contact.name,
              phoneNumber: contact.number,
              latitude,
              longitude,
            })
            .then(() => console.log("Call logged"))
            .catch((err) => console.error(err));

          // Make the actual call
          window.location.href = `tel:${contact.number}`;
        });
      } else {
        // If location not available, still log call without coords
        await axios.post("http://localhost:5001/api/calls", {
          contactName: contact.name,
          phoneNumber: contact.number,
          latitude,
          longitude,
        });
        window.location.href = `tel:${contact.number}`;
      }
    } catch (err) {
      console.error(err);
    }
  };

  return (
    <div className="emergency-container">
      <h1>🚨 Emergency Contacts</h1>

      <div className="contact-grid">
        {contacts.map((contact, index) => (
          <div key={index} className="contact-card">
            <h3>{contact.name}</h3>
            <p>{contact.number}</p>
            <button className="call-btn" onClick={() => handleCall(contact)}>
              📞 Call Now
            </button>
          </div>
        ))}
      </div>

      <button className="back-btn" onClick={() => navigate("/")}>
        ⬅ Back to Home
      </button>
    </div>
  );
};

export default Emergency;
